    return 10.0*min(abs(np.log(t/x)) for x in s)
FEAT = {"out": _f_out, "cent": _f_cent, "digit": _f_digit, "parity": _f_parity, "ratio": _f_ratio}[os.environ.get("FEAT","out")]
